/**
 * The animated icon catalog: one entry per icon file in src/components/nx-icons/icons.
 * The slug is the file name; `component` is the exported React component.
 */

export type IconCategory = "loaders" | "interface" | "arrows" | "tools" | "communication" | "commerce" | "files" | "health" | "food" | "play" | "science" | "places" | "education" | "business" | "nature" | "devices" | "security" | "media" | "weather" | "everyday" | "text" | "toggles" | "design" | "development";

export type IconMeta = {
  slug: string;
  /** The exported component, e.g. BellIcon. */
  component: string;
  /** Display name, e.g. Bell. */
  title: string;
  category: IconCategory;
  /** loop: plays on its own, forever. hover: plays while the pointer is over it. */
  kind: "loop" | "hover";
  /** The colour of its accent details when the Spark look is on. */
  accent: string;
  /** In plain words, what its sound is (every icon has its own, timed to its animation). */
  heard: string;
  /** An icon driven by a state prop lists its states here. */
  states?: string[];
  tags: string[];
  description: string;
  createdAt: string;
  /** Pro icons: anyone can preview and play them; their code and sound need Pro. */
  premium: boolean;
};

